// ===== SETTINGS (sirf yahi badalna hai) =====
const MAX = 2;                 // ek run me kitne candidates. PEHLE 2 se test karo, phir 20-25
const WORK = true;             // work (office) email dhoondo   (~$0.0005-0.03 sirf milne par)
const PERSONAL = true;         // personal email (gmail etc.)  (~$0.04-0.10 sirf milne par)
// Har call ka max kharcha "Treg work email" / "Treg personal email" node ke header X-Treg-Route-Max-Cost me hai.
// ============================================
// Kaun chuna jaata hai: Enriched + Exact, jinka Treg abhi tak check nahi hua; email nahi / pakka nahi wale pehle.
const slug = u => (String(u || '').match(/linkedin\.com\/in\/([^/?#]+)/i) || [])[1]?.toLowerCase() || '';
// pehle check ho chuke (error wale dobara try honge)
const done = new Set($('Read Treg_results').all().map(i => i.json)
  .filter(x => !(x.notes && !x['work email'] && !x['personal email'])).map(x => slug(x.linkedin_url)).filter(Boolean));
const goodEmail = r => r.email && /^(valid|verified)/i.test(String(r.email_status || '')) && !/guess|check/i.test(String(r.email_status || ''));
const score = r => (!r.email ? 6 : goodEmail(r) ? 0 : 4) + (r.open_to_work === 'Yes' ? 3 : 0) + (/senior|lead|manager/i.test(r.seniority || '') ? 1 : 0)
  + String(r.last_updated || r.first_seen || '').localeCompare('2026-10-01') * 0.5;
const take = (node, tab) => $(node).all().map(i => i.json)
  .filter(r => r.linkedin_url && slug(r.linkedin_url) && !done.has(slug(r.linkedin_url)))
  .filter(r => ['Enriched', 'Talent-pool ready'].includes(r.readiness) && r.title_match === 'Exact')
  .filter(r => !/treg checked/i.test(String(r.notes || '')))
  .sort((a, b) => score(b) - score(a))
  .map(r => ({ tab, row: r }));
const sn = take('Read ServiceNow rows', 'ServiceNow'), ai = take('Read AI_ML rows', 'AI_ML');
const picks = [];
while (picks.length < MAX && (sn.length || ai.length)) {
  if (sn.length) picks.push(sn.shift());
  if (picks.length < MAX && ai.length) picks.push(ai.shift());
}
return picks.map(({ tab, row: r }) => {
  const url = String(r.linkedin_url).replace('://in.linkedin.com', '://www.linkedin.com').replace(/\/+$/, '');
  const name = String(r.name || '').replace(/\s+[A-Z]\.?$/, '').trim();
  // WORK/PERSONAL false ho to khali body jaati hai: Treg use refuse karta hai, koi charge nahi
  return { json: { _tab: tab, _row: r, work: WORK ? { linkedin_url: url, full_name: name || undefined } : {},
    personal: PERSONAL ? { linkedin_url: url } : {} } };
});

// Treg jawab -> (1) sheet tab update  (2) MongoDB treg_* fields  (3) Treg_results row  (4) stats
const picks = $('Pick candidates').all().map(i => i.json);
const work = $('Treg work email').all().map(i => i.json);
const pers = $input.all().map(i => i.json);
const now = new Date(Date.now() + 5.5 * 3600e3);
const today = now.toISOString().slice(0, 10), stamp = now.toISOString().slice(0, 16).replace('T', ' ');
const norm = u => String(u || '').replace('://in.linkedin.com', '://www.linkedin.com').toLowerCase().replace(/\/+$/, '');
const goodEmail = r => r.email && /^(valid|verified)/i.test(String(r.email_status || '')) && !/guess|check/i.test(String(r.email_status || ''));
const hdr = (res, k) => (res && res.headers && (res.headers[k] ?? res.headers[k.toLowerCase()])) || '';
// one Treg answer -> {email, verified, by, cost, error}
function read(res, asked) {
  if (!asked) return { email: '', verified: false, by: '', cost: 0, error: '', skipped: true };
  const b = (res && res.body !== undefined ? res.body : res) || {};
  const body = typeof b === 'string' ? (() => { try { return JSON.parse(b); } catch { return { error: b }; } })() : b;
  const code = Number(res && res.statusCode) || 200;
  const out = body.output || {};
  const cost = Number(hdr(res, 'x-treg-cost-micro') || body._treg?.cost_micro || 0) / 1e6;
  const err = code >= 400 || body.error ? String(body.error?.message || body.error || body.detail || body.message || `HTTP ${code}`).slice(0, 160) : '';
  return { email: out.email || '', verified: !!out.verified, by: String(hdr(res, 'x-treg-served-by') || body._treg?.served_by || ''), cost, error: err };
}
const st = { stamp, checked: picks.length, work: 0, personal: 0, emailsAdded: 0, cost: 0, errors: 0, errorText: '' };
const out = [];
picks.forEach((pk, i) => {
  const r = pk._row, tab = pk._tab;
  const w = read(work[i], Object.keys(pk.work || {}).length > 0), p = read(pers[i], Object.keys(pk.personal || {}).length > 0);
  st.cost += w.cost + p.cost;
  for (const x of [w, p]) if (x.error && !x.skipped) { st.errors++; st.errorText = x.error; }
  if (w.email) st.work++;
  if (p.email) st.personal++;
  const sheet = { linkedin_url: r.linkedin_url, last_updated: today };
  const changed = [];
  if (w.email && !goodEmail(r) && (w.verified || !r.email)) {
    Object.assign(sheet, { email: w.email, email_status: `Treg ${w.verified ? 'verified' : 'found - not verified'}${w.by ? ' (' + w.by + ')' : ''}`, contact_source: 'Treg' });
    changed.push(w.verified ? 'work email (verified)' : 'work email'); st.emailsAdded++;
  } else if (p.email && !r.email) {
    Object.assign(sheet, { email: p.email, email_status: 'Personal email (Treg)', contact_source: 'Treg' }); changed.push('personal email'); st.emailsAdded++;
  }
  const errTxt = [w.error && 'work: ' + w.error, p.error && 'personal: ' + p.error].filter(Boolean).join('; ');
  const failed = errTxt && !w.email && !p.email;   // error: sheet ko mat chhuo, agle run me dobara try hoga
  if (!failed) sheet.notes = `${r.notes || ''}; Treg checked ${today}: ${changed.length ? changed.join(', ') : errTxt ? 'error' : 'nothing new'}${p.email && sheet.email !== p.email ? ' | personal email ' + p.email : ''}`.replace(/^; /, '');
  const mongo = { linkedin_url: norm(r.linkedin_url), treg_status: errTxt && !w.email && !p.email ? 'Error' : (w.email || p.email) ? 'Found' : 'Not found',
    treg_work_email: w.email, treg_work_verified: w.verified ? 'yes' : (w.email ? 'no' : ''), treg_personal_email: p.email,
    treg_served_by: [w.by, p.by].filter(Boolean).join(', '), treg_cost: Math.round((w.cost + p.cost) * 10000) / 10000, treg_checked_at: stamp };
  const log = { 'Checked at': stamp, pool: tab === 'AI_ML' ? 'AI/ML' : 'ServiceNow', name: r.name, linkedin_url: r.linkedin_url,
    'work email': w.email, 'work verified': w.email ? (w.verified ? 'yes' : 'no') : '', 'work served by': w.by, 'personal email': p.email,
    'personal served by': p.by, 'cost ($)': Math.round((w.cost + p.cost) * 10000) / 10000, 'what changed in sheet': changed.join(', ') || 'nothing', notes: errTxt };
  out.push({ json: { _tab: tab, sheet: failed ? null : sheet, mongo, log } });
});
if (!out.length) return [];
st.cost = Math.round(st.cost * 10000) / 10000;
out[0].json._stats = st;
return out;

const s = $('Build updates').first().json._stats;
const notes = `Treg: ${s.checked} checked. Work emails: ${s.work}, personal emails: ${s.personal}. Added to sheet: ${s.emailsAdded} emails. Cost $${s.cost}${s.errorText ? '. Error: ' + s.errorText : ''}`;
return [{ json: {
  sheet: { 'Run date': s.stamp, 'Flow': 'n8n (treg)', 'Queries': 0, 'Google results': '', 'LinkedIn profiles found': s.checked,
    'Rejected (not India / wrong title / duplicate)': 0, 'New rows added': `${s.emailsAdded} emails`, 'Apify cost ($)': s.cost, 'Notes': notes },
  mongo: { run_at: s.stamp, flow: 'n8n (treg)', found: s.checked, rejected: 0, added: `${s.emailsAdded} emails`, cost: s.cost,
    checked: s.checked, work_found: s.work, personal_found: s.personal, emails_added: s.emailsAdded, notes,
    error: s.errors && !s.work && !s.personal && s.errors >= s.checked ? s.errorText : '' },
} }];
